 var real=expedition.context.dungeon;encounterObject=new GameObject("Encounter spawn verification");var encounter=encounterObject.AddComponent<BasicEnemyEncounter>();encounter.startOnPlay=false;encounter.player=p;encounter.prefabs=real.prefabs;encounter.spawnPoints=real.spawnPoints;encounter.expeditionPrefab=real.expeditionPrefab;encounter.expeditionResidents=real.expeditionResidents;Check(encounter.BeginEncounter(1,new[]{EnemyKind.Swordsman,EnemyKind.Swordsman,EnemyKind.Swordsman}),"Encounter rejected");Check(encounter.GetComponentsInChildren<BasicEnemy>().Length==3,"Did not instantiate three enemies"); var enemy=encounter.GetComponentsInChildren<BasicEnemy>()[0];guard.SetGuard(false);typeof(ShinobiGuard).GetField("nextParry",F).SetValue(guard,0f);guard.SetGuard(true);hit.direction=-p.transform.forward;hit.source=enemy.gameObject;Check(guard.Resolve(hit)==0&&enemy.IsStunned,"Parry did not stun actual enemy");guard.SetGuard(false);ap.Play("Movement");p.GetComponent<ThirdPersonPresentation>().SendMessage("LateUpdate");Check(ap.Body.GetLayerWeight(ap.Body.GetLayerIndex("Weapon carry"))==1,"Weapon carry layer inactive");
