 }finally{if(guard){guard.SetGuard(false);guard.enabled=true;}if(encounterObject)UnityEngine.Object.Destroy(encounterObject);InputSystem.RemoveDevice(mouse);original?.MakeCurrent();p.SprintRequested=false;cc.enabled=false;p.transform.position=saved;cc.enabled=true;p.enabled=true;UnityEngine.Object.Destroy(floor);Cursor.lockState=CursorLockMode.None;}
